	"Define how to collect the outputs of the ad-hoc subprocess. The output collection variable stores the list of results; the output element expression defines what each element contributes. ": "Defina cómo recopilar las salidas del subproceso ad-hoc. La variable de colección de salida almacena la lista de resultados; la expresión del elemento de salida define qué aporta cada elemento. ",
	"Define static metadata passed to job workers alongside each job. Headers are not evaluated by the engine — use them for fixed worker configuration (e.g. ": "Defina metadatos estáticos que se pasan a los job workers junto con cada job. Las cabeceras no son evaluadas por el motor — úselas para configuración fija del worker (p. ej. ",
	"Define the assignment, schedule, and priority of the user task. Assignee, candidate groups, and candidate users can be combined. Use due date and follow-up date to express deadlines and urgency. ": "Defina la asignación, la planificación y la prioridad de la tarea de usuario. El asignado, los grupos candidatos y los usuarios candidatos pueden combinarse. Use la fecha de vencimiento y la fecha de seguimiento para expresar plazos y urgencia. ",
	"Define the completion behavior of an ad-hoc subprocess. If no completion condition is set, it will be completed after all active elements have been completed. ": "Defina el comportamiento de finalización de un subproceso ad-hoc. Si no se establece ninguna condición de finalización, se completará cuando todos los elementos activos hayan finalizado. ",
	"Define the decision to evaluate and how to map back the evaluation result. ": "Defina la decisión a evaluar y cómo asignar el resultado de la evaluación. ",
