	"Define the completion behavior of an ad-hoc subprocess. If no completion condition is set, it will be completed after all active elements have been completed. ": "Définissez le comportement d'achèvement d'un sous-processus ad-hoc. Si aucune condition d'achèvement n'est définie, il sera achevé une fois que tous les éléments actifs auront été achevés. ",
	"Define the decision to evaluate and how to map back the evaluation result. ": "Définissez la décision à évaluer et la manière de reporter le résultat de l'évaluation. ",
