	"Define an input collection expression that defines the collection to iterate over (e.g. ": "定义输入集合表达式，用于指定要遍历的集合（例如 ",
	"Define how to collect the outputs of the ad-hoc subprocess. The output collection variable stores the list of results; the output element expression defines what each element contributes. ": "定义如何收集临时子流程的输出。输出集合变量保存结果列表；输出元素表达式定义每个元素的贡献内容。 ",
	"Define static metadata passed to job workers alongside each job. Headers are not evaluated by the engine — use them for fixed worker configuration (e.g. ": "定义随每个作业一并传递给 job worker 的静态元数据。请求头不会被引擎求值——请用于 worker 的固定配置（例如 ",
