	"Define the completion behavior of an ad-hoc subprocess. If no completion condition is set, it will be completed after all active elements have been completed. ": "定义临时子流程的完成行为。若未设置完成条件，则在所有活动元素完成后结束。 ",
	"Define the decision to evaluate and how to map back the evaluation result. ": "定义要执行的决策以及如何映射回执行结果。 ",
	"Define the error to catch. Specify an error code (e.g. ": "定义要捕获的错误。请指定错误代码（例如 ",
	"Define the error to throw. Specify an error code (e.g. ": "定义要抛出的错误。请指定错误代码（例如 ",
	"Define the FEEL expression to evaluate and the variable to store the result in. ": "定义要求值的 FEEL 表达式以及用于保存结果的变量。 ",
	"Define the ID of the process to call (e.g. ": "定义要调用的流程 ID（例如 ",
