	"Define a boolean condition expression that determines when this sequence flow is taken. ": "Задайте логическое выражение условия, определяющее, когда используется этот поток управления. ",
	"Define a collection of elements which will be activated when the ad-hoc subprocess is reached. ": "Задайте коллекцию элементов, которые будут активированы при достижении ad-hoc подпроцесса. ",
	"Define an input collection expression that defines the collection to iterate over (e.g. ": "Задайте выражение входной коллекции, определяющее коллекцию для перебора (напр. ",
	"Define how to collect the outputs of the ad-hoc subprocess. The output collection variable stores the list of results; the output element expression defines what each element contributes. ": "Определите, как собирать результаты ad-hoc подпроцесса. Переменная выходной коллекции хранит список результатов; выражение выходного элемента определяет вклад каждого элемента. ",
	"Define static metadata passed to job workers alongside each job. Headers are not evaluated by the engine — use them for fixed worker configuration (e.g. ": "Задайте статические метаданные, передаваемые job worker'ам вместе с каждой задачей. Заголовки не вычисляются движком — используйте их для фиксированной конфигурации worker'а (напр. ",
	"Define the assignment, schedule, and priority of the user task. Assignee, candidate groups, and candidate users can be combined. Use due date and follow-up date to express deadlines and urgency. ": "Задайте назначение, сроки и приоритет пользовательской задачи. Исполнителя, группы-кандидаты и пользователей-кандидатов можно комбинировать. Используйте срок выполнения и дату контроля, чтобы обозначить сроки и срочность. ",
	"Define the completion behavior of an ad-hoc subprocess. If no completion condition is set, it will be completed after all active elements have been completed. ": "Задайте поведение завершения ad-hoc подпроцесса. Если условие завершения не задано, он завершится после завершения всех активных элементов. ",
	"Define the decision to evaluate and how to map back the evaluation result. ": "Задайте вычисляемое решение и способ сопоставления результата вычисления. ",
	"Define the error to catch. Specify an error code (e.g. ": "Задайте перехватываемую ошибку. Укажите код ошибки (напр. ",
	"Define the error to throw. Specify an error code (e.g. ": "Задайте вызываемую ошибку. Укажите код ошибки (напр. ",
	"Define the FEEL expression to evaluate and the variable to store the result in. ": "Задайте вычисляемое выражение FEEL и переменную для сохранения результата. ",
	"Define the ID of the process to call (e.g. ": "Задайте ID вызываемого процесса (напр. ",
