	"Add custom logic that reacts to various events in the workflow execution life-cycle. ": "워크플로 실행 수명 주기의 다양한 이벤트에 반응하는 사용자 정의 로직을 추가합니다. ",
	"Add input mappings to control what is passed to the activity as local variables. ": "입력 매핑을 추가하여 로컬 변수로 액티비티에 전달되는 내용을 제어합니다. ",
	"Add output mappings to control which variables are merged back into the process scope. ": "출력 매핑을 추가하여 어떤 변수를 프로세스 범위로 다시 병합할지 제어합니다. ",
