	"Control which variables from the called process are merged back into the parent scope. By default, all child variables are propagated; use output mappings to selectively return specific variables. ": "호출된 프로세스의 어떤 변수를 상위 범위로 다시 병합할지 제어합니다. 기본적으로 모든 자식 변수가 전파되며, 특정 변수만 선택적으로 반환하려면 출력 매핑을 사용하십시오. ",
