	"Define a boolean condition expression that determines when this sequence flow is taken. ": "이 시퀀스 플로가 선택되는 시점을 결정하는 불리언 조건 표현식을 정의합니다. ",
	"Define a collection of elements which will be activated when the ad-hoc subprocess is reached. ": "애드혹 서브프로세스에 도달했을 때 활성화될 요소의 컬렉션을 정의합니다. ",
	"Define an input collection expression that defines the collection to iterate over (e.g. ": "반복할 컬렉션을 정의하는 입력 컬렉션 표현식을 정의하십시오 (예: ",
	"Define how to collect the outputs of the ad-hoc subprocess. The output collection variable stores the list of results; the output element expression defines what each element contributes. ": "애드혹 서브프로세스의 출력을 수집하는 방법을 정의합니다. 출력 컬렉션 변수는 결과 목록을 저장하고, 출력 요소 표현식은 각 요소가 기여하는 내용을 정의합니다. ",
	"Define static metadata passed to job workers alongside each job. Headers are not evaluated by the engine — use them for fixed worker configuration (e.g. ": "각 작업과 함께 job worker에 전달되는 정적 메타데이터를 정의합니다. 헤더는 엔진에서 평가되지 않으며 — worker의 고정 구성에 사용하십시오 (예: ",
	"Define the assignment, schedule, and priority of the user task. Assignee, candidate groups, and candidate users can be combined. Use due date and follow-up date to express deadlines and urgency. ": "사용자 작업의 할당, 일정 및 우선순위를 정의합니다. 담당자, 후보 그룹, 후보 사용자를 함께 지정할 수 있습니다. 기한과 후속 조치 날짜를 사용하여 마감일과 긴급도를 표현하십시오. ",
	"Define the completion behavior of an ad-hoc subprocess. If no completion condition is set, it will be completed after all active elements have been completed. ": "애드혹 서브프로세스의 완료 동작을 정의합니다. 완료 조건이 설정되지 않으면 모든 활성 요소가 완료된 후에 완료됩니다. ",
	"Define the decision to evaluate and how to map back the evaluation result. ": "평가할 결정과 평가 결과를 다시 매핑하는 방법을 정의합니다. ",
	"Define the error to catch. Specify an error code (e.g. ": "포착할 오류를 정의합니다. 오류 코드를 지정하십시오 (예: ",
	"Define the error to throw. Specify an error code (e.g. ": "발생시킬 오류를 정의합니다. 오류 코드를 지정하십시오 (예: ",
	"Define the FEEL expression to evaluate and the variable to store the result in. ": "평가할 FEEL 표현식과 결과를 저장할 변수를 정의합니다. ",
