	"If turned on, all variables from the parent process instance will be propagated to the child process instance.": "활성화하면 부모 프로세스 인스턴스의 모든 변수가 자식 프로세스 인스턴스로 전파됩니다.",
	"Implement a script task using an inline FEEL expression. To add a custom implementation, use a job worker. ": "인라인 FEEL 표현식을 사용하여 스크립트 작업을 구현합니다. 사용자 정의 구현을 추가하려면 job worker를 사용하십시오. ",
	"Implement a user task managed by Camunda. To add a custom implementation, use a job worker. ": "Camunda가 관리하는 사용자 작업을 구현합니다. 사용자 정의 구현을 추가하려면 job worker를 사용하십시오. ",
